import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider, Container, Box, CssBaseline } from '@mui/material';
import theme from './theme';
import Header from './components/Header';
import ErrorBoundary from './components/ErrorBoundary';
import MSMERegistration from './components/MSMERegistration';
import UserLogin from './components/UserLogin';
import Dashboard from './components/Dashboard';
import CarbonFootprint from './components/CarbonFootprint';
import CarbonSavings from './components/CarbonSavings';
import Recommendations from './components/Recommendations';
import IncentivesScreen from './components/IncentivesScreen';
import ReportingScreen from './components/ReportingScreen';
import MultiAgentManagement from './components/MultiAgentManagement';
import MultiAgentDashboard from './components/MultiAgentDashboard';
import OptimizedMultiAgentDashboard from './components/OptimizedMultiAgentDashboard';
import GreenLoans from './components/GreenLoans';
import CarbonForecastingGraph from './components/CarbonForecastingGraph';
import DocumentUpload from './components/DocumentUpload';
import DocumentManagement from './components/DocumentManagement';
import DataPrivacy from './components/DataPrivacy';
import AICarbonEmailAgent from './components/AICarbonEmailAgent';
import ProtectedRoute from './components/ProtectedRoute';
import RequireMSME from './components/RequireMSME';
import RequireWorkflowPlanner from './components/RequireWorkflowPlanner';
import { RegistrationProvider } from './context/RegistrationContext';
import UserRegister from './components/UserRegister';
import ForgotPassword from './components/ForgotPassword';
import ResetPassword from './components/ResetPassword';
import MSMEList from './components/MSMEList';
import MSMEProfileSection from './components/MSMEProfileSection';
import { isAdminUserProfile } from './utils/authRole';
import {
  HelpCenterPage,
  PrivacyPolicyPage,
  SettingsPage,
  TermsOfServicePage,
} from './components/StaticPages';

interface RouteWrapperProps {
  children: React.ReactElement;
}

const OnboardedRoute: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>
      <RequireWorkflowPlanner>{children}</RequireWorkflowPlanner>
    </RequireMSME>
  </ProtectedRoute>
);

const RequireMSMEProfile: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>{children}</RequireMSME>
  </ProtectedRoute>
);

const AdminProfileRoute: React.FC<RouteWrapperProps> = ({ children }) => {
  if (!isAdminUserProfile()) {
    return <Navigate to="/dashboard" replace />;
  }

  return <ProtectedRoute>{children}</ProtectedRoute>;
};

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <RegistrationProvider>
          <ErrorBoundary>
            <Box sx={{ flexGrow: 1, minHeight: '100vh', backgroundColor: 'background.default' }}>
              <Header />

              <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                <Routes>
                  <Route
                    path="/msme-registration"
                    element={(
                      <ProtectedRoute>
                        <MSMERegistration />
                      </ProtectedRoute>
                    )}
                  />
                  <Route path="/" element={<UserLogin />} />
                  <Route path="/login" element={<UserLogin />} />
                  <Route path="/register" element={<UserRegister />} />
                  <Route path="/forgot-password" element={<ForgotPassword />} />
                  <Route path="/reset-password" element={<ResetPassword />} />
                  <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
                  <Route path="/terms-of-service" element={<TermsOfServicePage />} />
                  <Route path="/help" element={<HelpCenterPage />} />
                  <Route
                    path="/dashboard"
                    element={(
                      <OnboardedRoute>
                        <Dashboard />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/msme-list"
                    element={(
                      <OnboardedRoute>
                        <MSMEList />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/msme-profile"
                    element={(
                      <RequireMSMEProfile>
                        <MSMEProfileSection />
                      </RequireMSMEProfile>
                    )}
                  />
                  <Route
                    path="/msme-profile/workflow-planner"
                    element={(
                      <RequireMSMEProfile>
                        <MSMEProfileSection />
                      </RequireMSMEProfile>
                    )}
                  />
                  <Route
                    path="/carbon-footprint"
                    element={(
                      <OnboardedRoute>
                        <CarbonFootprint />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/ai-email-agent"
                    element={(
                      <OnboardedRoute>
                        <AICarbonEmailAgent />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/carbon-savings"
                    element={(
                      <OnboardedRoute>
                        <CarbonSavings />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/recommendations"
                    element={(
                      <OnboardedRoute>
                        <Recommendations />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/incentives"
                    element={(
                      <OnboardedRoute>
                        <IncentivesScreen />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/reporting"
                    element={(
                      <OnboardedRoute>
                        <ReportingScreen />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/multi-agent-management"
                    element={(
                      <AdminProfileRoute>
                        <MultiAgentManagement />
                      </AdminProfileRoute>
                    )}
                  />
                  <Route
                    path="/multi-agent-dashboard"
                    element={(
                      <AdminProfileRoute>
                        <MultiAgentDashboard />
                      </AdminProfileRoute>
                    )}
                  />
                  <Route
                    path="/optimized-multi-agent-dashboard"
                    element={(
                      <AdminProfileRoute>
                        <OptimizedMultiAgentDashboard />
                      </AdminProfileRoute>
                    )}
                  />
                  <Route
                    path="/green-loans"
                    element={(
                      <OnboardedRoute>
                        <GreenLoans />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/carbon-forecasting"
                    element={(
                      <OnboardedRoute>
                        <CarbonForecastingGraph />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/document-upload"
                    element={(
                      <OnboardedRoute>
                        <DocumentUpload />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/document-management"
                    element={(
                      <OnboardedRoute>
                        <DocumentManagement />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/data-privacy"
                    element={(
                      <OnboardedRoute>
                        <DataPrivacy />
                      </OnboardedRoute>
                    )}
                  />
                  <Route
                    path="/manufacturing-workflow"
                    element={(
                      <Navigate to="/msme-profile/workflow-planner" replace />
                    )}
                  />
                  <Route
                    path="/settings"
                    element={(
                      <OnboardedRoute>
                        <SettingsPage />
                      </OnboardedRoute>
                    )}
                  />
                  <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
              </Container>
            </Box>
        </ErrorBoundary>
      </RegistrationProvider>
    </ThemeProvider>
  );
}

export default App;