import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  Paper,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import {
  Business as BusinessIcon,
  PrecisionManufacturing as WorkflowIcon,
} from '@mui/icons-material';
import { useLocation, useNavigate } from 'react-router-dom';
import ApiService from '../services/api';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import { hasCompletedWorkflowPlanner } from '../utils/workflowCompletion';

interface MSMEProfileData {
  companyName?: string;
  companyType?: string;
  industry?: string;
  businessDomain?: string;
  udyamRegistrationNumber?: string;
  gstNumber?: string;
  panNumber?: string;
  contact?: {
    email?: string;
    phone?: string;
    address?: {
      street?: string;
      city?: string;
      state?: string;
      pincode?: string;
      country?: string;
    };
  };
  business?: {
    annualTurnover?: number;
    numberOfEmployees?: number;
    manufacturingUnits?: number;
    manufacturingWorkflow?: any;
  };
}

const MSMEProfileSection: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [profile, setProfile] = useState<MSMEProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const activeTab = useMemo(
    () => (location.pathname.endsWith('/workflow-planner') ? 1 : 0),
    [location.pathname]
  );

  useEffect(() => {
    const loadProfile = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await ApiService.getMSMEProfile();
        setProfile(response?.data || null);
      } catch (err) {
        setProfile(null);
        setError(err instanceof Error ? err.message : 'Unable to load MSME profile.');
      } finally {
        setLoading(false);
      }
    };

    loadProfile();
  }, []);

  const workflowCompleted = hasCompletedWorkflowPlanner(profile?.business?.manufacturingWorkflow);

  const handleTabChange = (_: React.SyntheticEvent, newValue: number) => {
    if (newValue === 0) {
      navigate('/msme-profile');
      return;
    }

    navigate('/msme-profile/workflow-planner');
  };

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
          MSME Profile
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Manage company information and workflow planning in one place.
        </Typography>
      </Box>

      <Paper sx={{ mb: 3 }}>
        <Tabs value={activeTab} onChange={handleTabChange}>
          <Tab icon={<BusinessIcon />} iconPosition="start" label="Profile Details" />
          <Tab icon={<WorkflowIcon />} iconPosition="start" label="Workflow Planner" />
        </Tabs>
      </Paper>

      {activeTab === 0 ? (
        <>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {error}
            </Alert>
          ) : !profile ? (
            <Alert
              severity="info"
              action={(
                <Button color="inherit" size="small" onClick={() => navigate('/msme-registration')}>
                  Complete registration
                </Button>
              )}
            >
              MSME profile is not available yet.
            </Alert>
          ) : (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                      <Typography variant="h6" sx={{ fontWeight: 700 }}>
                        Company Information
                      </Typography>
                      <Chip
                        color={workflowCompleted ? 'success' : 'warning'}
                        label={workflowCompleted ? 'Workflow planner completed' : 'Workflow planner pending'}
                      />
                    </Box>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Name</Typography>
                        <Typography variant="body1">{profile.companyName || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Type</Typography>
                        <Typography variant="body1">{profile.companyType || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Industry</Typography>
                        <Typography variant="body1">{profile.industry || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Business Domain</Typography>
                        <Typography variant="body1">{profile.businessDomain || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">UDYAM Number</Typography>
                        <Typography variant="body1">{profile.udyamRegistrationNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">GST Number</Typography>
                        <Typography variant="body1">{profile.gstNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">PAN Number</Typography>
                        <Typography variant="body1">{profile.panNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Contact Email</Typography>
                        <Typography variant="body1">{profile.contact?.email || 'Not provided'}</Typography>
                      </Grid>
                    </Grid>
                    <Box sx={{ mt: 2 }}>
                      <Button variant="outlined" onClick={() => navigate('/msme-profile/workflow-planner')}>
                        Open Workflow Planner
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </>
      ) : (
        <ManufacturingWorkflowPlanner />
      )}
    </Box>
  );
};

export default MSMEProfileSection;
