import React from 'react';
import {
  Box,
  Button,
  Divider,
  List,
  ListItem,
  ListItemText,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  Gavel as TermsIcon,
  HelpOutline as HelpIcon,
  Security as PrivacyIcon,
  Settings as SettingsIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { useRegistration } from '../context/RegistrationContext';

interface PageShellProps {
  icon: React.ReactNode;
  title: string;
  subtitle: string;
  children: React.ReactNode;
}

const PageShell: React.FC<PageShellProps> = ({ icon, title, subtitle, children }) => (
  <Box
    sx={{
      minHeight: '70vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      py: 4,
      px: 2,
    }}
  >
    <Paper
      elevation={2}
      sx={{
        width: '100%',
        maxWidth: 900,
        p: { xs: 3, md: 5 },
        borderRadius: 3,
        border: '1px solid rgba(76, 175, 80, 0.12)',
      }}
    >
      <Stack spacing={1.5} sx={{ mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
          {icon}
          <Typography variant="h4" component="h1" sx={{ fontWeight: 700 }}>
            {title}
          </Typography>
        </Box>
        <Typography color="text.secondary">{subtitle}</Typography>
      </Stack>
      <Divider sx={{ mb: 3 }} />
      {children}
    </Paper>
  </Box>
);

export const HelpCenterPage: React.FC = () => (
  <PageShell
    icon={<HelpIcon color="primary" fontSize="large" />}
    title="Help Center"
    subtitle="Quick answers and support options for using Carbon Intelligence."
  >
    <Typography variant="h6" sx={{ mb: 1.5 }}>
      Frequently asked questions
    </Typography>
    <List dense sx={{ mb: 2 }}>
      <ListItem>
        <ListItemText
          primary="How do I start using the platform?"
          secondary="Sign in, open the dashboard, and complete your MSME profile to unlock insights."
        />
      </ListItem>
      <ListItem>
        <ListItemText
          primary="How can I reset my password?"
          secondary="Use the Forgot Password flow on the login page to receive a secure reset link."
        />
      </ListItem>
      <ListItem>
        <ListItemText
          primary="Where can I view uploaded files?"
          secondary="Use the Documents page from the top navigation to review and manage your files."
        />
      </ListItem>
    </List>

    <Typography variant="body1" sx={{ mb: 2 }}>
      Need more help? Contact support at <strong>support@carbonintelligence.ai</strong>.
    </Typography>

    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
      <Button component={RouterLink} to="/login" variant="contained">
        Back to Login
      </Button>
      <Button component={RouterLink} to="/privacy-policy" variant="outlined">
        Privacy Policy
      </Button>
    </Stack>
  </PageShell>
);

export const PrivacyPolicyPage: React.FC = () => (
  <PageShell
    icon={<PrivacyIcon color="primary" fontSize="large" />}
    title="Privacy Policy"
    subtitle="How we handle your data on the Carbon Intelligence platform."
  >
    <Typography paragraph>
      We collect only the information needed to provide carbon analytics, compliance workflows, and reporting
      features for MSMEs.
    </Typography>
    <Typography paragraph>
      Your account and business data is used for authentication, analytics generation, and platform improvements.
      Sensitive fields are processed with access controls and encrypted storage.
    </Typography>
    <Typography paragraph>
      For privacy requests or questions, contact <strong>privacy@carbonintelligence.ai</strong>.
    </Typography>

    <Button component={RouterLink} to="/terms-of-service" variant="outlined">
      View Terms of Service
    </Button>
  </PageShell>
);

export const TermsOfServicePage: React.FC = () => (
  <PageShell
    icon={<TermsIcon color="primary" fontSize="large" />}
    title="Terms of Service"
    subtitle="Rules for using Carbon Intelligence and its data services."
  >
    <Typography paragraph>
      By using this platform, you agree to provide accurate information and use the service in compliance with
      applicable laws and regulations.
    </Typography>
    <Typography paragraph>
      Recommendations and analytics are provided to support decision-making and should be validated against your
      operational context before implementation.
    </Typography>
    <Typography paragraph>
      Access may be suspended for unauthorized use, security violations, or abuse of platform resources.
    </Typography>

    <Button component={RouterLink} to="/help" variant="outlined">
      Visit Help Center
    </Button>
  </PageShell>
);

export const SettingsPage: React.FC = () => {
  const { registrationData } = useRegistration();

  return (
    <PageShell
      icon={<SettingsIcon color="primary" fontSize="large" />}
      title="Settings"
      subtitle="Manage your account preferences and support options."
    >
      <Typography paragraph>
        Account email: <strong>{registrationData?.email || 'Not available'}</strong>
      </Typography>
      <Typography paragraph>
        More account settings will be added here in upcoming updates. For immediate support, use the Help Center.
      </Typography>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
        <Button component={RouterLink} to="/dashboard" variant="contained">
          Back to Dashboard
        </Button>
        <Button component={RouterLink} to="/help" variant="outlined">
          Open Help Center
        </Button>
      </Stack>
    </PageShell>
  );
};
