import React, { useEffect, useState } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import ApiService from '../services/api';
import { hasCompletedWorkflowPlanner } from '../utils/workflowCompletion';

interface RequireWorkflowPlannerProps {
  children: React.ReactElement;
}

const RequireWorkflowPlanner: React.FC<RequireWorkflowPlannerProps> = ({ children }) => {
  const location = useLocation();
  const [isLoading, setIsLoading] = useState(true);
  const [redirectPath, setRedirectPath] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const checkWorkflowStatus = async () => {
      setIsLoading(true);
      setRedirectPath(null);

      try {
        const response = await ApiService.getMSMEProfile();
        const workflow = response?.data?.business?.manufacturingWorkflow;
        const isWorkflowCompleted = hasCompletedWorkflowPlanner(workflow);

        if (!isWorkflowCompleted && isMounted) {
          setRedirectPath('/msme-profile/workflow-planner');
        }
      } catch (error: any) {
        if (!isMounted) {
          return;
        }

        if (error?.message?.toLowerCase().includes('not found')) {
          setRedirectPath('/msme-registration');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    checkWorkflowStatus();

    return () => {
      isMounted = false;
    };
  }, [location.pathname]);

  if (isLoading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '45vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (redirectPath) {
    return <Navigate to={redirectPath} replace state={{ from: location }} />;
  }

  return children;
};

export default RequireWorkflowPlanner;
